Read the Data sheet and build sums/counts by GL account and period. For each Summary row, compute the monthly forecast as the sum of actuals in E:G divided by 12-D3. Write actual sums where a matching Data record exists and the forecast otherwise into Summary!E6:P9.

```python
import shutil, openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb["Summary"]
data_ws = vals["Data"]
sum_vals = vals["Summary"]

def norm(v):
    if v is None:
        return None
    if isinstance(v, bool):
        return v
    if isinstance(v, (int, float)):
        f = float(v)
        return int(f) if f.is_integer() else f
    s = str(v).strip()
    try:
        f = float(s)
        return int(f) if f.is_integer() else f
    except ValueError:
        return s

d3 = norm(sum_vals["D3"].value)
try:
    d3_int = int(float(d3))
except Exception:
    d3_int = 0

denom = 12 - d3_int
if denom == 0:
    denom = 1

actual_sum = {}
actual_count = {}

for row in data_ws.iter_rows(min_row=2, max_row=data_ws.max_row, min_col=1, max_col=4):
    gl = norm(row[0].value)
    period = norm(row[3].value)
    if gl is None or period is None:
        continue

    try:
        amt = float(row[2].value)
    except (TypeError, ValueError):
        amt = 0.0

    key = (gl, period)
    actual_sum[key] = actual_sum.get(key, 0.0) + amt
    actual_count[key] = actual_count.get(key, 0) + 1

rows = range(6, 10)
cols = range(5, 17)

row_actual = {}
for r in rows:
    gl = norm(sum_vals.cell(row=r, column=3).value)
    total = 0.0
    for c in range(5, 8):  # E through G
        p = norm(sum_vals.cell(row=5, column=c).value)
        total += actual_sum.get((gl, p), 0.0)
    row_actual[r] = total

forecast = {r: (row_actual[r] / denom if denom else 0.0) for r in rows}

for r in rows:
    gl = norm(sum_vals.cell(row=r, column=3).value)
    for c in cols:
        p = norm(sum_vals.cell(row=5, column=c).value)
        key = (gl, p)

        if actual_count.get(key, 0) > 0:
            v = actual_sum.get(key, 0.0)
        else:
            v = forecast[r]

        v = round(float(v), 2)
        if v == int(v):
            v = int(v)

        ws.cell(row=r, column=c).value = v

wb.save(OUT)

print("D3:", d3_int, "denom:", denom)
for r in rows:
    print(r, [ws.cell(row=r, column=c).value for c in cols])
